style.css:
@-moz-document domain("youtube.com") {
:root {
    --pipboy-green: #4aff4a;
    --pipboy-green-dim: #1f8f1f;
    --pipboy-bg: #000000;
}

html, body, ytd-app {
    background: var(--pipboy-bg) !important;
    color: var(--pipboy-green) !important;
    font-family: "Share Tech Mono", "VT323", "Courier New", monospace !important;
}

ytd-app *:not(img):not(svg) {
    background-color: transparent !important;
    color: var(--pipboy-green) !important;
    border-color: var(--pipboy-green-dim) !important;
    text-shadow: 0 0 3px var(--pipboy-green), 0 0 8px rgba(74, 255, 74, 0.4) !important;
}

/* Fondos de bloques clave que YouTube pinta aparte */
ytd-masthead,
#masthead-container,
ytd-guide-renderer,
tp-yt-app-drawer,
ytd-watch-flexy,
#secondary,
#comments,
ytd-browse,
ytd-two-column-browse-results-renderer {
    background: var(--pipboy-bg) !important;
}

/* Íconos SVG a verde */
ytd-app svg, ytd-app path {
    fill: var(--pipboy-green) !important;
    stroke: var(--pipboy-green) !important;
}

/* Barra de progreso del reproductor de video */
.ytp-progress-bar-container,
.ytp-play-progress,
.ytp-swatch-background-color {
    background-color: var(--pipboy-green) !important;
}

h1, h2, h3, #video-title, ytd-video-meta-block {
    letter-spacing: 0.5px;
}

/* Miniaturas en monocromo verde, como una holocinta */
ytd-thumbnail img,
#thumbnail img,
.ytp-videowall-still-image {
    filter: grayscale(1) sepia(1) hue-rotate(60deg) saturate(3) brightness(0.85) contrast(1.1) !important;
}

/* Scanlines MUY sutiles, sin el estilo marcado de la versión anterior */
ytd-app::before {
    content: "";
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: repeating-linear-gradient(
        0deg,
        rgba(0, 0, 0, 0.12) 0px,
        rgba(0, 0, 0, 0.12) 1px,
        transparent 1px,
        transparent 3px
    );
    pointer-events: none;
    z-index: 9998;
    mix-blend-mode: multiply;
}

/* Viñeta ligera, sin el "cierre" agresivo */
ytd-app::after {
    content: "";
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: radial-gradient(
        ellipse at center,
        rgba(0, 0, 0, 0) 65%,
        rgba(0, 0, 0, 0.25) 100%
    );
    pointer-events: none;
    z-index: 9999;
}

/* Parpadeo casi imperceptible, solo para dar vida sin molestar */
@keyframes pipboy-flicker-soft {
    0%, 100% { opacity: 1; }
    97% { opacity: 1; }
    98% { opacity: 0.95; }
    99% { opacity: 1; }
}

ytd-app::after {
    animation: pipboy-flicker-soft 8s infinite;
}

/* Scrollbar a juego */
::-webkit-scrollbar {
    width: 10px;
    background: #050a05;
}
::-webkit-scrollbar-thumb {
    background: var(--pipboy-green-dim);
    border: 1px solid var(--pipboy-green);
}
}
